import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.DebugInfo{PlayerUniqueID: -300, Data: []byte("lag spike")}
LAG_SPIKE = bytes.fromhex("d704096c6167207370696b65")

# generated by gophertunnel b8bd735:
# &packet.DebugInfo{PlayerUniqueID: 7, Data: nil}
EMPTY = bytes.fromhex("0e00")

# generated by gophertunnel b8bd735:
# &packet.DebugInfo{PlayerUniqueID: 0, Data: bytes.Repeat([]byte("x"), 200)}
LONG = bytes.fromhex(
    "00c80178787878787878787878787878787878787878787878787878787878787878787878787878"
    "7878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "7878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "7878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "78787878787878787878787878"
)

GOLDENS = [
    pytest.param(v2225.DebugInfoPacket(actor_id=-300, data="lag spike"), LAG_SPIKE, id="lag-spike"),
    pytest.param(v2225.DebugInfoPacket(actor_id=7, data=""), EMPTY, id="empty"),
    pytest.param(v2225.DebugInfoPacket(actor_id=0, data="x" * 200), LONG, id="two-byte-length"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_debug_info_is_packet_155(version):
    assert version.packets[155] is version.DebugInfoPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_debug_info_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_debug_info_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
